#include <iostream>
#include <string>
#include <cctype>
using namespace std;

int main() {
    string a;
    cin >> a;

    int upper = 0, lower = 0;

    for (char c : a) {
        if (islower(static_cast<unsigned char>(c)))
            ++lower;
        else if (isupper(static_cast<unsigned char>(c)))
            ++upper;
    }

    for (char& c : a) {
        if (lower > upper)
            c = static_cast<char>(tolower(static_cast<unsigned char>(c)));
        else
            c = static_cast<char>(toupper(static_cast<unsigned char>(c)));
    }

    cout << a;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string a;
    cin >> a;

    int big = 0, small = 0;

    for (char c : a) {
        if (c >= 'a' && c <= 'z')
            ++small;
        else if (c >= 'A' && c <= 'Z')
            ++big;
    }

    if (small >= big) {
        for (char& c : a) {
            if (c >= 'A' && c <= 'Z')
                c += 'a' - 'A';
        }
    } else {
        for (char& c : a) {
            if (c >= 'a' && c <= 'z')
                c -= 'a' - 'A';
        }
    }

    cout << a;
    return 0;
}

